<?php
$records=array_filter($all['items'],fn($i)=>(!param($_GET,'q') || mb_stripos($i['title'].' '.$i['author'],param($_GET,'q'))!==false) && (!param($_GET,'status') || match(param($_GET,'status')) {'pending'=>!empty($i['pending']),'hidden'=>!empty($i['hidden']),'published'=>empty($i['pending']) && empty($i['hidden']),default=>true}));
usort($records,fn($a,$b)=>strcmp($b['date']??'',$a['date']??''));
[$records,$page,$pages,$total]=admin_page($records,24);
?>
<form class="admin-filter-form" action="/admin/artworks"><input type="search" name="q" aria-label="Search artwork" value="<?= e(param($_GET,'q')) ?>" placeholder="Search artwork or artist"><select name="status" aria-label="Filter visibility"><?php foreach([''=>'All artwork','published'=>'Published','pending'=>'Awaiting approval','hidden'=>'Hidden'] as $key=>$label): ?><option value="<?= $key ?>" <?= param($_GET,'status')===$key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select><button>Search artwork</button></form><p><?= number_format($total) ?> artworks</p>
<div class="member-upload-grid"><?php foreach($records as $item): ?><article class="member-upload"><a href="/art/<?= (int)$item['id'] ?>"><img src="<?= e(media_url($item)) ?>" alt="<?= e($item['title']) ?>"><h2><?= e($item['title']) ?></h2></a><p>By <?= e($item['author']) ?></p><p class="status-pill <?= !empty($item['hidden']) ? 'status-hidden' : (empty($item['pending']) ? 'status-published' : '') ?>"><?= !empty($item['hidden']) ? 'Hidden' : (!empty($item['pending']) ? 'Awaiting approval' : 'Published') ?></p><div class="review-actions"><a href="/art/<?= (int)$item['id'] ?>/edit">Edit details →</a><form method="post" action="/admin/visibility"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="quiet-button"><?= !empty($item['hidden']) ? 'Unhide artwork' : 'Hide artwork' ?></button></form></div></article><?php endforeach; ?></div><?php admin_pagination('/admin/artworks',$page,$pages); ?>
